    ? $('Rank Website Candidates').first()?.json?.candidate_url 
    : null;

  const urlList = [
    $('Normalize Input').first()?.json?.candidate_url,
    resolveCandidateUrl,
    ...($('Find Growth Signals').all().map(item => item.json.url)),
    ...($json.sources || [])
  ]
  .filter(Boolean)
  .map(url => String(url).trim())
  .filter(url => url.startsWith('http'));

  return {
    urls: Array.from(new Set(urlList))
  };
})() }}

