const INDUSTRY_KEYS = INDUSTRY_CATEGORIES.map((c) => c.key)
const NEED_KEYS = DIGITAL_NEEDS.map((c) => c.key)
const GROWTH_KEYS = GROWTH_SIGNALS.map((c) => c.key)
